-- AgentScope Studio: PostgreSQL schema only; contains no local user data or secrets.
-- Keep this schema private. Access through the authenticated Python backend.
BEGIN;
CREATE SCHEMA IF NOT EXISTS agentscope;
SET LOCAL search_path TO agentscope, pg_catalog;
CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS sessions ( id TEXT PRIMARY KEY, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '' , user_id TEXT, title TEXT NOT NULL DEFAULT '', pinned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_tokens ( token TEXT PRIMARY KEY, user_id TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) );
CREATE TABLE IF NOT EXISTS channel_access ( id TEXT PRIMARY KEY, binding_id TEXT NOT NULL, tenant_id TEXT NOT NULL, sender_id TEXT NOT NULL, chat_id TEXT NOT NULL, is_group INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(binding_id,tenant_id,sender_id,chat_id));
CREATE TABLE IF NOT EXISTS channel_bindings ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, platform TEXT NOT NULL, name TEXT NOT NULL, config_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'disabled', error TEXT NOT NULL DEFAULT '', last_received TEXT NOT NULL DEFAULT '', last_sent TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, UNIQUE(user_id,platform));
CREATE TABLE IF NOT EXISTS channel_messages ( id TEXT PRIMARY KEY,binding_id TEXT NOT NULL,event_id TEXT NOT NULL, session_id TEXT NOT NULL DEFAULT '',text TEXT NOT NULL,route_cipher TEXT NOT NULL, scope_json TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(binding_id,event_id));
CREATE TABLE IF NOT EXISTS channel_outbox ( id TEXT PRIMARY KEY,binding_id TEXT NOT NULL,message_id TEXT NOT NULL, delivery_key TEXT NOT NULL UNIQUE,route_cipher TEXT NOT NULL,text TEXT NOT NULL, status TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channel_secrets (binding_id TEXT PRIMARY KEY, cipher TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channel_sessions ( session_id TEXT PRIMARY KEY, binding_id TEXT NOT NULL, user_id TEXT NOT NULL, tenant_id TEXT NOT NULL,sender_id TEXT NOT NULL,chat_id TEXT NOT NULL, agent_id TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS console_resources ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, content TEXT NOT NULL, enabled INTEGER NOT NULL, config_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS console_runs ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, resource_id TEXT NOT NULL, name TEXT NOT NULL, session_id TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL , step_index INTEGER NOT NULL DEFAULT 0, snapshot_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS execution_scopes (session_id TEXT PRIMARY KEY, user_id TEXT NOT NULL, config_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_docs ( id TEXT PRIMARY KEY, path TEXT NOT NULL UNIQUE, title TEXT NOT NULL, content TEXT NOT NULL, content_hash TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS messages ( id TEXT PRIMARY KEY, session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL, parts_json TEXT NOT NULL DEFAULT '[]', FOREIGN KEY (session_id) REFERENCES sessions(id) );
CREATE TABLE IF NOT EXISTS model_settings ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, provider TEXT NOT NULL, display_name TEXT NOT NULL, model_name TEXT NOT NULL, endpoint TEXT NOT NULL DEFAULT '', api_key TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) );
CREATE TABLE IF NOT EXISTS plans ( id TEXT PRIMARY KEY, session_id TEXT NOT NULL, plan TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (session_id) REFERENCES sessions(id) );
CREATE TABLE IF NOT EXISTS runtime_events ( id TEXT PRIMARY KEY, session_id TEXT NOT NULL, event_type TEXT NOT NULL, title TEXT NOT NULL, detail TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (session_id) REFERENCES sessions(id) );
CREATE TABLE IF NOT EXISTS skill_market_users (user_id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS user_onboarding ( user_id TEXT PRIMARY KEY, bootstrap_seen_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) );
CREATE INDEX IF NOT EXISTS console_resources_owner ON console_resources(user_id, kind);
CREATE INDEX IF NOT EXISTS messages_session_created_idx ON messages(session_id, created_at ASC);
CREATE INDEX IF NOT EXISTS model_settings_user_idx ON model_settings(user_id, is_default DESC, updated_at DESC);
CREATE INDEX IF NOT EXISTS plans_session_created_idx ON plans(session_id, created_at DESC);
CREATE INDEX IF NOT EXISTS runtime_events_session_created_idx ON runtime_events(session_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS users_username_lower_unique ON users (lower(username));
ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sessions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "auth_tokens" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "channel_access" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "channel_bindings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "channel_messages" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "channel_outbox" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "channel_secrets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "channel_sessions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "console_resources" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "console_runs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "execution_scopes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "knowledge_docs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "messages" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "model_settings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "plans" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "runtime_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "skill_market_users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "user_onboarding" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON SCHEMA agentscope FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA agentscope FROM PUBLIC, anon, authenticated;
COMMIT;
SELECT count(*) AS business_tables, bool_and(rowsecurity) AS all_rls_enabled FROM pg_tables WHERE schemaname = 'agentscope';
